import SwiftUI

/// The OFFICIAL Drive mark (assets/drive/, locked by
/// DEC-drive-mark-official): a sporty flat-bottom D-rim steering wheel with
/// the Cline head as its hub — antenna nub, pill-eye cutouts (even-odd).
/// Two layers per the motion doc: the wheel may turn; Cline stays upright.
/// Generated from cline-drive-mark-layers.svg (viewBox 1024) — do not edit.
private func driveScaled(_ rect: CGRect) -> (ox: CGFloat, oy: CGFloat, s: CGFloat) {
    let s = min(rect.width, rect.height) / 1024.0
    return (rect.midX - 512.0 * s, rect.midY - 512.0 * s, s)
}

